import{_ as a,c as t,o as r,ae as o}from"./chunks/framework.CliRSA9F.js";const i="/images/pr_outreach.webp",g=JSON.parse('{"title":"PR Outreach","description":"","frontmatter":{},"headers":[],"relativePath":"features/pr-outreach.md","filePath":"features/pr-outreach.md"}'),s={name:"features/pr-outreach.md"};function n(l,e,u,d,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="pr-outreach" tabindex="-1">PR Outreach <a class="header-anchor" href="#pr-outreach" aria-label="Permalink to &quot;PR Outreach&quot;">​</a></h1><h2 id="manage-your-podcast-pitch-pipeline" tabindex="-1">Manage Your Podcast Pitch Pipeline <a class="header-anchor" href="#manage-your-podcast-pitch-pipeline" aria-label="Permalink to &quot;Manage Your Podcast Pitch Pipeline&quot;">​</a></h2><p>PR Outreach provides a Kanban-style CRM for tracking your podcast promotion efforts. Manage pitch targets, track follow-ups, and move opportunities through your pipeline from initial contact to successful feature.</p><p><img src="'+i+'" alt="PR Outreach Pipeline" width="600px" style="display:block;margin:0 auto;"></p><h2 id="your-outreach-pipeline" tabindex="-1">Your Outreach Pipeline <a class="header-anchor" href="#your-outreach-pipeline" aria-label="Permalink to &quot;Your Outreach Pipeline&quot;">​</a></h2><p>The pipeline organizes your outreach efforts into five stages:</p><h3 id="identified" tabindex="-1">Identified <a class="header-anchor" href="#identified" aria-label="Permalink to &quot;Identified&quot;">​</a></h3><p>Targets you&#39;ve discovered but haven&#39;t contacted yet. These are opportunities waiting for your first pitch — editorial contacts, newsletter curators, podcast directories, or media outlets.</p><h3 id="contacted" tabindex="-1">Contacted <a class="header-anchor" href="#contacted" aria-label="Permalink to &quot;Contacted&quot;">​</a></h3><p>Pitches you&#39;ve sent that are awaiting response. When you move a card here, PodSEO records the pitch date automatically.</p><h3 id="replied" tabindex="-1">Replied <a class="header-anchor" href="#replied" aria-label="Permalink to &quot;Replied&quot;">​</a></h3><p>Active conversations where you&#39;ve received a response. These are warm leads that need nurturing toward a feature.</p><h3 id="featured" tabindex="-1">Featured <a class="header-anchor" href="#featured" aria-label="Permalink to &quot;Featured&quot;">​</a></h3><p>Success! Targets that have featured your podcast. The feature date is recorded automatically when you move a card here.</p><h3 id="declined" tabindex="-1">Declined <a class="header-anchor" href="#declined" aria-label="Permalink to &quot;Declined&quot;">​</a></h3><p>Opportunities that didn&#39;t work out. Keeping these helps you track conversion rates and learn from what didn&#39;t resonate.</p><h2 id="pipeline-features" tabindex="-1">Pipeline Features <a class="header-anchor" href="#pipeline-features" aria-label="Permalink to &quot;Pipeline Features&quot;">​</a></h2><h3 id="summary-dashboard" tabindex="-1">Summary Dashboard <a class="header-anchor" href="#summary-dashboard" aria-label="Permalink to &quot;Summary Dashboard&quot;">​</a></h3><p>At the top, a funnel summarizes your progress across four key stages at a glance:</p><ul><li><strong>Identified</strong> - How many targets are ready to pitch</li><li><strong>Contacted</strong> - Active outreach awaiting responses</li><li><strong>Replied</strong> - Conversations in progress</li><li><strong>Featured</strong> - Successful features achieved</li></ul><p>The funnel focuses on these four stages. Declined still appears as its own column on the board below, so you can keep a record of opportunities that didn&#39;t work out, but it isn&#39;t part of the funnel summary.</p><h3 id="overdue-follow-ups" tabindex="-1">Overdue Follow-ups <a class="header-anchor" href="#overdue-follow-ups" aria-label="Permalink to &quot;Overdue Follow-ups&quot;">​</a></h3><p>An alert appears when you have follow-ups past their scheduled date. Timely follow-ups are crucial for successful outreach - don&#39;t let opportunities go cold.</p><h3 id="target-cards" tabindex="-1">Target Cards <a class="header-anchor" href="#target-cards" aria-label="Permalink to &quot;Target Cards&quot;">​</a></h3><p>Each pipeline card shows:</p><ul><li>Target name and domain</li><li>Current status</li><li>Any notes you&#39;ve added</li><li>Scheduled follow-up date</li></ul><h3 id="drag-and-drop-management" tabindex="-1">Drag-and-Drop Management <a class="header-anchor" href="#drag-and-drop-management" aria-label="Permalink to &quot;Drag-and-Drop Management&quot;">​</a></h3><p>Move targets between columns as your relationship progresses. Drag a card from &quot;Contacted&quot; to &quot;Replied&quot; when you get a response, or to &quot;Featured&quot; when you achieve success.</p><h2 id="managing-your-targets" tabindex="-1">Managing Your Targets <a class="header-anchor" href="#managing-your-targets" aria-label="Permalink to &quot;Managing Your Targets&quot;">​</a></h2><h3 id="adding-targets" tabindex="-1">Adding Targets <a class="header-anchor" href="#adding-targets" aria-label="Permalink to &quot;Adding Targets&quot;">​</a></h3><p>Two ways to add pitch targets:</p><p><strong>Add Custom Target</strong> - Create your own entry with:</p><ul><li>Target name (person or publication)</li><li>Email address</li><li>Domain/website</li><li>Notes about the opportunity</li></ul><p><strong>Find Opportunities</strong> - Opens a panel with PodSEO&#39;s curated list of pitch targets. This includes platform editorial submission pages (such as <strong>Apple Podcasts Editorial</strong> and <strong>Spotify Editorial</strong>) alongside podcast newsletters, directories, blogs, and curated recommendation sites worth pitching — for example, Goodpods, EarBuds Podcast Collective, and All Hear. Click <strong>Add</strong> on any opportunity to create a card in your Identified column. Each opportunity includes a description and, where available, the submission or contact link you&#39;ll need to pitch your podcast.</p><h3 id="target-details" tabindex="-1">Target Details <a class="header-anchor" href="#target-details" aria-label="Permalink to &quot;Target Details&quot;">​</a></h3><p>Click any target card to open a detail modal showing:</p><ul><li><strong>Contact information</strong> — Name, email, Twitter handle, and submission page URL (where available)</li><li><strong>Notes</strong> — Free-text area for tracking your pitch history and conversation details (auto-saves)</li><li><strong>Follow-up reminder</strong> — Set a date and PodSEO will alert you when it&#39;s due</li><li><strong>Status selector</strong> — Change the pipeline stage directly from the modal</li><li><strong>Timeline</strong> — When the target was added, when you pitched, and when you were featured</li></ul><h3 id="scheduling-follow-ups" tabindex="-1">Scheduling Follow-ups <a class="header-anchor" href="#scheduling-follow-ups" aria-label="Permalink to &quot;Scheduling Follow-ups&quot;">​</a></h3><p>For each target, set a follow-up date. PodSEO will alert you when follow-ups are due so you stay on top of your outreach.</p><h2 id="outreach-best-practices" tabindex="-1">Outreach Best Practices <a class="header-anchor" href="#outreach-best-practices" aria-label="Permalink to &quot;Outreach Best Practices&quot;">​</a></h2><h3 id="building-your-pipeline" tabindex="-1">Building Your Pipeline <a class="header-anchor" href="#building-your-pipeline" aria-label="Permalink to &quot;Building Your Pipeline&quot;">​</a></h3><ul><li><strong>Start with research</strong> - Identify publications, newsletters, and platforms that feature podcasts like yours</li><li><strong>Quality over quantity</strong> - Focus on relevant targets rather than mass outreach</li><li><strong>Mix target types</strong> - Include editorial contacts, newsletter curators, and industry publications</li></ul><h3 id="effective-pitching" tabindex="-1">Effective Pitching <a class="header-anchor" href="#effective-pitching" aria-label="Permalink to &quot;Effective Pitching&quot;">​</a></h3><ul><li><strong>Personalize each pitch</strong> - Reference specific content or explain why you&#39;re a good fit</li><li><strong>Be concise</strong> - Busy editors appreciate brief, clear pitches</li><li><strong>Include value</strong> - Explain what&#39;s in it for their audience</li><li><strong>Make it easy</strong> - Provide assets, links, and everything they need</li></ul><h3 id="following-up" tabindex="-1">Following Up <a class="header-anchor" href="#following-up" aria-label="Permalink to &quot;Following Up&quot;">​</a></h3><ul><li><strong>Schedule systematically</strong> - Set follow-up dates for every contact</li><li><strong>Be persistent but respectful</strong> - 2-3 follow-ups is appropriate</li><li><strong>Add value each time</strong> - Share news, new episodes, or relevant angles</li><li><strong>Know when to move on</strong> - Not every pitch will convert</li></ul><h3 id="learning-from-success" tabindex="-1">Learning from Success <a class="header-anchor" href="#learning-from-success" aria-label="Permalink to &quot;Learning from Success&quot;">​</a></h3><p>Track what works in your Featured column:</p><ul><li>Which pitch angles resonated</li><li>What types of targets converted</li><li>Timing patterns that worked</li><li>Content that attracted features</li></ul><h2 id="integration-with-my-placements" tabindex="-1">Integration with My Placements <a class="header-anchor" href="#integration-with-my-placements" aria-label="Permalink to &quot;Integration with My Placements&quot;">​</a></h2><p>PR Outreach helps you actively pursue features, while <a href="/features/my-placements.html">My Placements</a> tracks where features appear. Together they give you a complete picture of your editorial visibility efforts and results.</p><h2 id="why-pr-outreach-also-boosts-your-ai-visibility" tabindex="-1">Why PR Outreach Also Boosts Your AI Visibility <a class="header-anchor" href="#why-pr-outreach-also-boosts-your-ai-visibility" aria-label="Permalink to &quot;Why PR Outreach Also Boosts Your AI Visibility&quot;">​</a></h2><p>Landing your podcast on websites — newsletters, review sites, and &quot;best [topic] podcasts&quot; listicles — does more than reach human readers. AI assistants like ChatGPT, Claude, Perplexity, and Gemini build their podcast recommendations largely from what they read on the open web, and they tend to weigh these website recommendations more heavily than signals from the listening platforms themselves. Every roundup or article that names your show becomes a source an assistant can draw on when a listener asks for recommendations. That makes a disciplined PR Outreach pipeline one of the most effective ways to improve your <a href="/features/ai-mentions.html">AI Mentions</a> visibility, not just your traditional media coverage.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>PR Outreach is available to Pro subscribers. The pipeline helps you systematically grow your podcast&#39;s media presence.</p><p><strong>Related Features</strong>: Check <a href="/features/my-placements.html">My Placements</a> to see where your podcast has been featured, use <a href="/features/curated-lists.html">Curated Lists</a> to research editorial opportunities, and track the payoff in <a href="/features/ai-mentions.html">AI Mentions</a> as web recommendations feed AI discovery.</p>',56)])])}const m=a(s,[["render",n]]);export{g as __pageData,m as default};
